  colors: themeColorsSchema,
  iconColors: themeIconColorsSchema,
  createdAt: z.string(),
  updatedAt: z.string(),
  isActive: z.boolean()
});

export type CustomTheme = z.infer<typeof customThemeSchema>;

// Input schema for saving a theme (without id, userId, timestamps, isActive)
